{% if chapters.size > 0 %}
<june-scroll-chapters class="jcs{% if settings.june_type_enabled != false and section.settings.use_master_typography != false %} june-type{% endif %}" id="JuneChapters-{{ section.id }}" data-scroll="{{ section.settings.scroll }}" data-motion="{{ section.settings.motion }}" data-editor="{{ request.design_mode }}" data-pace="{{ section.settings.pace }}" data-pace-mobile="{{ section.settings.pace_mobile }}" data-blank="{{ section.settings.blank_hold }}" data-blank-mobile="{{ section.settings.blank_mobile }}" aria-label="{{ section.settings.eyebrow | escape }}" style="--jcs-secondary:{{ section.settings.flower_secondary }};--jcs-product:{{ section.settings.product_size }};--jcs-mobile:{{ section.settings.product_mobile }}">
 <div class="jcs__stage">
 <a class="jcs__skip" href="#JuneChaptersEnd-{{ section.id }}">{{ section.settings.skip | escape }}</a>
  <div class="jcs__flowers" aria-hidden="true">{% for n in (1..26) %}<svg viewBox="0 0 100 100"><g fill="currentColor"><ellipse cx="50" cy="26" rx="15" ry="24"/><ellipse cx="50" cy="26" rx="15" ry="24" transform="rotate(60 50 50)"/><ellipse cx="50" cy="26" rx="15" ry="24" transform="rotate(120 50 50)"/><ellipse cx="50" cy="26" rx="15" ry="24" transform="rotate(180 50 50)"/><ellipse cx="50" cy="26" rx="15" ry="24" transform="rotate(240 50 50)"/><ellipse cx="50" cy="26" rx="15" ry="24" transform="rotate(300 50 50)"/></g><circle cx="50" cy="50" r="12" fill="var(--jc-ink)"/></svg>{% endfor %}</div>
  {% for block in chapters %}
   {% liquid
    case block.settings.effect
     when 'petals'
      assign asset = 'https://cdn.shopify.com/s/files/1/0177/5579/9606/files/june-chapter-wedding-cutout.png?v=1790664256'
     when 'wipe'
      assign asset = 'https://cdn.shopify.com/s/files/1/0177/5579/9606/files/june-chapter-rewritable-cutout.png?v=1790664263'
     else
      assign asset = 'https://cdn.shopify.com/s/files/1/0177/5579/9606/files/june-chapter-baby-cutout.png?v=1790664268'
    endcase
   %}
   <article class="jcs__scene" data-scene data-block="{{ block.id }}" {{ block.shopify_attributes }} aria-labelledby="JuneChapterTitle-{{ section.id }}-{{ forloop.index0 }}">
    <div class="jcs__product">{% if block.settings.cutout != blank %}{{ block.settings.cutout | image_url: width: 1200 | image_tag: widths: '400,600,900,1200', sizes: '(max-width: 900px) 75vw, 480px', alt: block.settings.alt, loading: 'lazy' }}{% else %}<img src="{{ asset }}" width="900" height="1100" alt="{{ block.settings.alt | escape }}" loading="lazy">{% endif %}</div>
    <div class="jcs__copy"><h2 class="jcs__heading" id="JuneChapterTitle-{{ section.id }}-{{ forloop.index0 }}">{{ block.settings.heading | escape }} <span>{{ block.settings.heading_second | escape }}</span></h2><div class="jcs__body">{{ block.settings.body }}</div></div>
   </article>
  {% endfor %}
  <div class="jcs__duster" aria-hidden="true"><svg viewBox="0 0 180 110"><path d="M12 61 137 39 169 65 46 94Z" fill="var(--jc-ink)"/><path d="M12 34 137 12 169 38 46 66Z" fill="var(--jc-accent)"/><path d="M12 34 46 66 46 87 12 57Z" fill="var(--jc-accent)"/><path d="M46 66 169 38 169 59 46 87Z" fill="var(--jc-accent)"/><path d="M46 66 169 38" stroke="var(--jc-ink)" stroke-opacity=".3"/><path d="M58 39 120 27" stroke="var(--jc-ink)" stroke-width="4" stroke-linecap="round" opacity=".35"/></svg></div>
  <div class="jcs__footprints" aria-hidden="true">{% for n in (1..16) %}<svg viewBox="0 0 50 90"><path d="M20 78C7 77 7 65 13 54c5-10 0-15-2-23-3-10 4-18 14-17 13 1 17 13 12 23-6 13-5 18-4 27 1 9-3 16-13 14Z"/><ellipse cx="13" cy="8" rx="6" ry="8"/><ellipse cx="25" cy="6" rx="4.5" ry="6"/><ellipse cx="35" cy="9" rx="4" ry="5"/><ellipse cx="42" cy="16" rx="3.5" ry="4.5"/></svg>{% endfor %}</div>
 </div>
</june-scroll-chapters><div id="JuneChaptersEnd-{{ section.id }}" tabindex="-1"></div>
{% endif %}
{% stylesheet %}
.jcs{display:block;position:relative;background:var(--jc-bg);color:var(--jc-ink);isolation:isolate}.jcs__stage{position:relative;max-width:1680px;margin:auto;overflow:hidden;background:var(--jc-bg)}.jcs__scene{display:flex;flex-direction:column;align-items:center;justify-content:center;gap:24px;padding:48px 24px;text-align:center;min-height:600px}.jcs__product{height:330px;width:min(480px,80vw);flex:none}.jcs__product img{width:100%;height:100%;object-fit:contain;display:block;filter:drop-shadow(0 12px 12px #241c1814)}.jcs__copy{max-width:780px}.jcs .jcs__heading{font-family:var(--jc-heading-font);font-weight:var(--jc-heading-weight);font-size:var(--jc-heading-size);letter-spacing:var(--jc-heading-tracking);line-height:var(--jc-heading-leading);margin:0 0 16px}.jcs__heading span{display:block}.jcs .jcs__body{font-family:var(--jc-body-font);font-weight:var(--jc-body-weight);font-size:var(--jc-body-size);letter-spacing:var(--jc-body-tracking);line-height:var(--jc-body-leading);max-width:540px;margin:auto}.jcs__body p{margin:0}.jcs__body strong{font-weight:700}.jcs__skip{position:absolute;right:16px;top:12px;z-index:10;min-height:44px;display:flex;align-items:center;border:1px solid currentColor;padding:12px 18px;border-radius:30px;background:var(--jc-bg);color:var(--jc-ink);font:var(--jc-button-weight) var(--jc-button-size)/var(--jc-button-leading) var(--jc-button-font);letter-spacing:var(--jc-button-tracking)}.jcs__skip:focus-visible{outline:3px solid var(--jc-ink);outline-offset:3px}.jcs__flowers,.jcs__duster,.jcs__footprints{display:none;position:absolute;inset:0;pointer-events:none}.jcs[data-pinned=true]{height:var(--jcs-runway)}.jcs[data-pinned=true] .jcs__stage{position:sticky;top:var(--jcs-top);height:var(--jcs-height)}.jcs[data-pinned=true] .jcs__scene{position:absolute;inset:0;min-height:0;padding:20px;gap:20px;opacity:0;visibility:hidden;will-change:transform,opacity;pointer-events:none}.jcs[data-pinned=true] .jcs__product{height:calc(var(--jcs-height)*var(--jcs-product)/100)}.jcs[data-pinned=true] .jcs__flowers,.jcs[data-pinned=true] .jcs__footprints{display:block;z-index:2}.jcs__flowers svg{position:absolute;left:50%;top:45%;width:70px;height:70px;opacity:0;color:var(--jc-accent);will-change:transform,opacity}.jcs__flowers svg:nth-child(3n){color:var(--jcs-secondary)}.jcs__flowers svg:nth-child(3n + 1){color:var(--jc-ink)}.jcs[data-pinned=true] .jcs__duster{display:block;inset:auto;left:0;top:0;width:150px;height:100px;z-index:4;opacity:0;will-change:transform}.jcs__duster svg{width:100%;height:100%;filter:drop-shadow(0 10px 7px #241c1820)}.jcs__footprints svg{position:absolute;width:42px;height:76px;fill:var(--jc-ink);opacity:0;will-change:opacity,transform}.jcs:not([data-pinned=true]) .jcs__scene{opacity:1!important;visibility:visible!important;transform:none!important;clip-path:none!important}.jcs:not([data-pinned=true]) .jcs__scene+.jcs__scene{border-top:1px solid color-mix(in srgb,var(--june-ink,#171717) 8.24%,transparent)}
@media(max-width:900px){.jcs .jcs__heading{font-size:var(--jc-heading-mobile)}.jcs .jcs__body{font-size:var(--jc-body-mobile)}.jcs__scene{min-height:520px;padding:34px 20px}.jcs__product{height:260px}.jcs[data-pinned=true] .jcs__product{height:calc(var(--jcs-height)*var(--jcs-mobile)/100);width:80vw}.jcs[data-pinned=true] .jcs__scene{gap:18px}.jcs__copy{max-width:100%}.jcs .jcs__heading{margin-bottom:12px}.jcs__flowers svg{width:48px;height:48px}.jcs__footprints svg{width:30px;height:54px}.jcs[data-pinned=true] .jcs__duster{width:110px;height:75px}.jcs__skip{font-size:var(--jc-button-mobile)}}
@media(prefers-reduced-motion:reduce){.jcs__flowers,.jcs__duster,.jcs__footprints{display:none!important}}
