 connectedCallback(){this.controller?.abort();this.controller=new AbortController();const o={signal:this.controller.signal};this.stage=this.querySelector('.jcs__stage');this.scenes=[...this.querySelectorAll('[data-scene]')];this.flowers=[...this.querySelectorAll('.jcs__flowers svg')];this.feet=[...this.querySelectorAll('.jcs__footprints svg')];this.duster=this.querySelector('.jcs__duster');this.reduced=matchMedia('(prefers-reduced-motion: reduce)');this.onScroll=()=>{if(!this.frame)this.frame=requestAnimationFrame(()=>{this.frame=0;this.render()})};window.addEventListener('scroll',this.onScroll,{...o,passive:true});window.addEventListener('resize',()=>this.setup(),o);this.reduced.addEventListener('change',()=>this.setup(),o);this.querySelector('.jcs__skip').addEventListener('click',e=>{e.preventDefault();const end=document.getElementById(this.querySelector('.jcs__skip').hash.slice(1));const next=this.closest('[id^="shopify-section-"]')?.nextElementSibling;const target=next?.querySelector('h2')||end;if(!target)return;target.setAttribute('tabindex','-1');target.focus({preventScroll:true});window.scrollTo({top:window.scrollY+target.getBoundingClientRect().top-this.offset-16,behavior:'instant'});},o);this.addEventListener('shopify:block:select',e=>{const i=this.scenes.findIndex(s=>s.dataset.block===e.detail?.blockId);if(i>=0&&this.pinned){cancelAnimationFrame(this.selectionFrame);this.selectionFrame=requestAnimationFrame(()=>this.seekScene(i))}},o);this.setup()}
 seekScene(index){const phase=[2,5,8][index];if(phase===undefined)return;const beat=this.durations.slice(0,phase).reduce((a,b)=>a+b,0)+this.durations[phase]*.6;window.scrollTo({top:window.scrollY+this.getBoundingClientRect().top-this.offset+beat*this.unit,behavior:'instant'});this.render()}
 setup(){const mobile=innerWidth<=900;this.offset=Math.min(parseFloat(getComputedStyle(this).getPropertyValue('--jc-offset'))||0,mobile?64:90);this.height=Math.max(240,innerHeight-this.offset);this.pinned=this.dataset.scroll==='true'&&this.dataset.motion==='true'&&!this.reduced.matches&&innerHeight>=480;this.dataset.pinned=String(this.pinned);const pace=Math.max(10,Number(mobile?this.dataset.paceMobile:this.dataset.pace)||(mobile?19:32));this.unit=this.height*pace/100;const blank=Math.max(0,Math.min(mobile?12:20,Number(mobile?this.dataset.blankMobile:this.dataset.blank)||0))*innerHeight/100/this.unit;this.durations=[mobile?Math.min(blank,.2):blank,1.1,2,.8,blank,2,1.3,1.5,2,.8];this.total=this.durations.reduce((a,b)=>a+b,0);this.distance=this.total*this.unit;this.style.setProperty('--jcs-top',this.offset+'px');this.style.setProperty('--jcs-height',this.height+'px');this.style.setProperty('--jcs-runway',(this.distance+this.height)+'px');if(!this.pinned){this.scenes.forEach(s=>{s.inert=false;s.removeAttribute('aria-hidden')});return}this.render()}
 render(){if(!this.pinned)return;const rect=this.getBoundingClientRect();if(rect.top>innerHeight||rect.bottom<0)return;const clamp=v=>Math.max(0,Math.min(1,v)),ease=v=>v*v*(3-2*v);let time=Math.max(0,Math.min(this.total-.0001,(this.offset-rect.top)/this.unit)),phase=0;while(phase<this.durations.length-1&&time>this.durations[phase]){time-=this.durations[phase];phase++}const p=clamp(time/Math.max(.0001,this.durations[phase]));this.dataset.phase=['empty','flowers','wedding','wedding-exit','breathing-room','rewritable','duster','footsteps','baby','baby-exit'][phase];this.scenes.forEach(s=>{s.style.opacity='0';s.style.visibility='hidden';s.style.clipPath='none';s.inert=true;s.setAttribute('aria-hidden','true')});
 const show=(i,a=1,y=0,scale=1)=>{const s=this.scenes[i];if(!s)return;s.style.opacity=a;s.style.visibility=a>0?'visible':'hidden';s.style.transform=`translateY(${y}px) scale(${scale})`;s.inert=a<.8;s.setAttribute('aria-hidden',String(a<.8));};
 if(phase===2){const q=ease(clamp(p*4));show(0,q,(1-q)*75,.92+.08*q)}if(phase===3)show(0,1-ease(p),-p*this.height*.65,1-.08*p);
 if(phase===5){const q=ease(clamp(p*4));show(1,q,(1-q)*65,.94+.06*q)}
 if(phase===6){show(1);const passes=6,t=Math.min(5.999,p*passes),row=Math.floor(t),q=ease(t-row),right=row%2===0,x=right?q:1-q,top=100-(row+1)*100/passes,bottom=100-row*100/passes;this.scenes[1].style.clipPath=right?`polygon(0 0,100% 0,100% ${bottom}%,${x*100}% ${bottom}%,${x*100}% ${top}%,0 ${top}%)`:`polygon(0 0,100% 0,100% ${top}%,${x*100}% ${top}%,${x*100}% ${bottom}%,0 ${bottom}%)`;this.duster.style.transform=`translate(${x*this.stage.clientWidth-this.duster.offsetWidth/2}px,${(top+bottom)/200*this.height-this.duster.offsetHeight/2}px) rotate(${right?-12:12}deg)`}
