{% schema %}
{
  "name": "June · Other chapters",
  "tag": "section",
  "class": "june-chapters-section",
  "settings": [
    {
      "type": "checkbox",
      "id": "use_master_typography",
      "label": "Use approved master typography",
      "default": true,
      "info": "Homepage small text and prices use Theme settings > June typography. Turn off for section typography."
    },
    {
      "type": "checkbox",
      "id": "use_master_palette",
      "label": "Use master palette",
      "default": true,
      "info": "Uses Theme settings > June master palette. Turn off to use this section’s individual colours."
    },
    {
      "type": "text",
      "id": "eyebrow",
      "label": "Eyebrow",
      "default": "Other chapters"
    },
    {
      "type": "text",
      "id": "skip",
      "label": "Skip link",
      "default": "Skip to shopping"
    },
    {
      "type": "checkbox",
      "id": "scroll",
      "label": "Enable pinned scroll story",
      "default": true
    },
    {
      "type": "checkbox",
      "id": "motion",
      "label": "Enable decorative motion",
      "default": true
    },
    {
      "type": "range",
      "id": "offset",
      "label": "Sticky header clearance",
      "min": 0,
      "max": 150,
      "step": 5,
      "unit": "px",
      "default": 85
    },
    {
      "type": "font_picker",
      "id": "fallback_font",
      "label": "Fallback font",
      "default": "poppins_n4"
    },
    {
      "type": "color",
      "id": "background",
      "label": "Story background",
      "default": "#FFFFFF"
    },
    {
      "type": "color",
      "id": "ink",
      "label": "Text",
      "default": "#171717"
    },
    {
      "type": "color",
      "id": "accent",
      "label": "Flowers and duster",
      "default": "#F56A28"
    },
    {
      "type": "color",
      "id": "flower_secondary",
      "label": "Secondary flower colour",
      "default": "#DADADA"
    },
    {
      "type": "range",
      "id": "pace",
      "label": "Desktop scroll pace",
      "min": 10,
      "max": 100,
      "step": 1,
      "unit": "vh",
      "default": 32,
      "info": "Scroll distance per beat. Lower values make the story shorter."
    },
    {
      "type": "range",
      "id": "blank_hold",
      "label": "Desktop blank pause",
      "min": 0,
      "max": 20,
      "step": 1,
      "default": 18,
      "info": "Scroll distance for each blank interval; not elapsed time.",
      "unit": "vh"
    },
    {
      "type": "range",
      "id": "product_size",
      "label": "Product height on desktop",
      "min": 25,
      "max": 55,
      "step": 1,
      "unit": "%",
      "default": 44
    },
    {
      "type": "range",
      "id": "product_mobile",
      "label": "Product height on mobile",
      "min": 25,
      "max": 50,
      "step": 1,
      "unit": "%",
      "default": 40
    },
    {
      "type": "range",
      "id": "pace_mobile",
      "label": "Mobile scroll pace",
      "min": 10,
      "max": 100,
      "step": 1,
      "default": 19,
      "unit": "vh"
    },
    {
      "type": "range",
      "id": "blank_mobile",
      "label": "Mobile blank pause",
      "min": 0,
      "max": 12,
      "step": 1,
      "default": 10,
      "unit": "vh",
      "info": "Scroll distance for each blank interval; not elapsed time."
    }
  ],
  "blocks": [
    {
      "type": "chapter",
      "name": "Chapter",
      "limit": 3,
      "settings": [
        {
          "type": "image_picker",
          "id": "cutout",
          "label": "Transparent product PNG",
          "info": "Overrides the prepared catalog cutout. Use a transparent background."
        },
        {
          "type": "text",
          "id": "label",
          "label": "Chapter name",
          "default": "Wedding"
        },
        {
          "type": "text",
          "id": "heading",
          "label": "Heading first line",
          "default": "For your next"
        },
        {
          "type": "text",
          "id": "heading_second",
          "label": "Heading second line",
          "default": "big yes."
        },
        {
          "type": "richtext",
          "id": "body",
          "label": "Supporting copy",
          "default": "<p>Make room for every wedding detail.</p>"
        },
        {
          "type": "product",
          "id": "product",
          "label": "Featured product"
        },
        {
          "type": "collection",
          "id": "collection",
          "label": "Shopping collection"
        },
        {
          "type": "checkbox",
          "id": "show_shop",
          "label": "Show shopping button",
          "default": true
        },
        {
          "type": "text",
          "id": "shop",
          "label": "Shopping label",
          "default": "Explore wedding planners"
        },
        {
          "type": "text",
          "id": "note",
          "label": "Optional status note"
        },
        {
          "type": "image_picker",
          "id": "image",
          "label": "Scene image override"
        },
        {
          "type": "range",
          "id": "image_number",
