{% stylesheet %}



june-corner.jcorner{display:grid;grid-template-columns:minmax(0,1.8fr) minmax(340px,1fr);grid-template-rows:auto 1fr auto;max-width:1680px;margin:auto;background:var(--jcorner-bg);color:var(--jcorner-ink);border-bottom:1px solid color-mix(in srgb,var(--june-ink,#171717) 13.33%,transparent)}

.jcorner *{box-sizing:border-box}.jcorner [hidden]{display:none!important}.jcorner h2,.jcorner h3,.jcorner p{margin:0;color:inherit}.jcorner a{color:inherit;text-decoration:none}.jcorner button{cursor:pointer;color:inherit;appearance:none}.jcorner strong{font-weight:700}.jcorner button:focus-visible,.jcorner a:focus-visible{outline:3px solid var(--jcorner-ink);outline-offset:4px}

.jcorner .jcorner__heading{font-family:var(--jcorner-heading-font);font-size:var(--jcorner-heading-size);font-weight:var(--jcorner-heading-weight);letter-spacing:var(--jcorner-heading-tracking);line-height:var(--jcorner-heading-leading)}

.jcorner .jcorner__title{font-family:var(--jcorner-title-font);font-size:var(--jcorner-title-size);font-weight:var(--jcorner-title-weight);letter-spacing:var(--jcorner-title-tracking);line-height:var(--jcorner-title-leading)}

.jcorner .jcorner__body{font-family:var(--jcorner-body-font);font-size:var(--jcorner-body-size);font-weight:var(--jcorner-body-weight);letter-spacing:var(--jcorner-body-tracking);line-height:var(--jcorner-body-leading)}

.jcorner .jcorner__button-type{font-family:var(--jcorner-button-font);font-size:var(--jcorner-button-size);font-weight:var(--jcorner-button-weight);letter-spacing:var(--jcorner-button-tracking);line-height:var(--jcorner-button-leading)}



.jcorner__header{grid-column:2;grid-row:1;padding:32px 32px 22px}.jcorner__eyebrow{text-transform:uppercase;font-size:calc(var(--jcorner-button-size)*.75)!important;letter-spacing:.12em!important}.jcorner .jcorner__heading{margin:16px 0 18px;overflow-wrap:break-word}

.jcorner__visual{grid-column:1;grid-row:1/4;min-width:0;background:var(--june-surface,#F5F5F3);display:flex;align-items:center}.jcorner__canvas{position:relative;width:100%;isolation:isolate}.jcorner__canvas picture,.jcorner__canvas img{display:block;width:100%;height:auto}.jcorner__placeholder{display:block;width:100%;height:auto}

.jcorner__spot{position:absolute;left:var(--spot-x);top:var(--spot-y);width:48px;height:48px;padding:5px;border:1px solid var(--june-border,#DADADA);border-radius:50%;background:color-mix(in srgb,var(--june-dark,#171717) 40%,transparent);color:var(--june-on-dark,#FFFFFF)!important;transform:translate(-50%,-50%);transition:background var(--jcorner-duration) ease,box-shadow var(--jcorner-duration) ease;box-shadow:0 2px 9px #17171733}.jcorner__spot span{display:grid;place-items:center;width:100%;height:100%;border-radius:50%;background:var(--june-dark,#171717)}.jcorner__spot[aria-pressed=true]{background:var(--jcorner-accent);border-color:var(--jcorner-accent);box-shadow:0 0 0 5px color-mix(in srgb,var(--june-border,#DADADA) 46.67%,transparent),0 3px 10px #17171733}.jcorner__spot[aria-pressed=true] span{color:var(--jcorner-accent)}

.jcorner__caption{position:absolute;bottom:0;left:0;right:0;padding:30px 28px 20px;background:linear-gradient(transparent,color-mix(in srgb,var(--june-dark,#171717) 60%,transparent));color:var(--june-on-dark,#FFFFFF)!important;pointer-events:none}

.jcorner__details{grid-column:2;grid-row:2;padding:0 32px;align-self:center}.jcorner__product{border-top:1px solid color-mix(in srgb,var(--june-ink,#171717) 26.67%,transparent);padding-top:18px}.jcorner__count{text-transform:uppercase;font-size:calc(var(--jcorner-button-size)*.75)!important;letter-spacing:.09em!important;margin-bottom:18px!important}.jcorner__item{display:grid;grid-template-columns:88px 1fr;gap:18px;align-items:center}.jcorner__item>img{display:block;width:88px;height:112px;object-fit:contain;mix-blend-mode:multiply}.jcorner__price{margin-top:8px!important}.jcorner__arrow{display:grid;place-items:center;width:30px;height:30px;flex:none;border-radius:50%;background:var(--june-dark,var(--june-dark,#171717));color:var(--june-on-dark,var(--jcorner-accent))}.jcorner__arrow svg{width:18px;height:18px}.jcorner .jcorner__link{display:inline-flex;align-items:center;gap:9px;min-height:44px;text-decoration:underline;text-underline-offset:5px;margin-top:8px}.jcorner__link .jcorner__arrow{width:22px;height:22px}.jcorner__link svg{width:14px;height:14px}

